text(await tools.exec_command({cmd:"cat >> /app/output/gen.py <<'PY'

def movebase(xy,yaw=None,grip=0,tag='base',max_steps=60):
    for n in range(max_steps):
        x=current(); d=np.asarray(xy)-x[:2]
        dy=0 if yaw is None else (yaw-x[2]+np.pi)%(2*np.pi)-np.pi
        if np.linalg.norm(d)<.004 and abs(dy)<.006:break
        a=np.zeros(11);a[:2]=d*min(1,.085/max(np.linalg.norm(d),1e-6));a[2]=np.clip(dy,-.1,.1);a[10]=grip
        res=submit(a,f'{tag}_{n:03}')
        if res.done:break
    return observe(tag)
